<?php
require_once 'config.php';
if (!isset($_SESSION['user_id']) || !in_array($_SESSION['role'], ['admin', 'teacher'], true)) { header('Location: login.php'); exit(); }
$unit_id = filter_input(INPUT_GET, 'unit_id', FILTER_VALIDATE_INT); $stmt = $pdo->prepare("SELECT u.*, c.title AS course_title, c.teacher_id FROM units u JOIN courses c ON c.course_id = u.course_id WHERE u.unit_id = ?"); $stmt->execute([$unit_id]); $unit = $stmt->fetch();
if (!$unit || ($_SESSION['role'] === 'teacher' && $unit['teacher_id'] != $_SESSION['user_id'])) { http_response_code(403); exit('ไม่มีสิทธิ์'); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $stmt = $pdo->prepare("INSERT INTO exams (course_id, unit_id, exam_type, title) VALUES (?, ?, ?, ?)"); $stmt->execute([$unit['course_id'], $unit_id, $_POST['exam_type'], trim($_POST['title'])]); header('Location: manage_exams.php?unit_id=' . $unit_id); exit(); }
$stmt = $pdo->prepare("SELECT * FROM exams WHERE unit_id = ? ORDER BY exam_id"); $stmt->execute([$unit_id]); $exams = $stmt->fetchAll(); include 'header.php';
?><h3 class="text-primary">ข้อสอบ: <?php echo htmlspecialchars($unit['title']); ?></h3><div class="card card-custom p-4 mb-4"><form method="POST" class="row g-2"><?php echo csrf_field(); ?><div class="col-md-4"><select class="form-select" name="exam_type"><option value="unit_pretest">แบบทดสอบก่อนเรียน</option><option value="unit_review">แบบทบทวน</option><option value="unit_posttest">แบบทดสอบหลังเรียน</option></select></div><div class="col-md-6"><input class="form-control" name="title" placeholder="ชื่อข้อสอบ" required></div><div class="col-md-2"><button class="btn btn-pastel">เพิ่มข้อสอบ</button></div></form></div><div class="list-group"><?php foreach ($exams as $exam): ?><a class="list-group-item list-group-item-action" href="manage_questions.php?exam_id=<?php echo (int)$exam['exam_id']; ?>"><?php echo htmlspecialchars($exam['title']); ?> <span class="badge bg-secondary float-end"><?php echo htmlspecialchars($exam['exam_type']); ?></span></a><?php endforeach; ?></div><?php include 'footer.php'; ?>